import{_ as a,o as n,c as p,a3 as t}from"./chunks/framework.Dz5Q8p4s.js";const o=JSON.parse('{"title":"Lost in Adaptation: Layer-Selective Recovery of Temporal Reasoning in Video-Language Models","description":"","frontmatter":{"title":"Lost in Adaptation: Layer-Selective Recovery of Temporal Reasoning in Video-Language Models","arxiv":"2604.11399","date":"2026-04-13","authors":"Zihang Fu, Haonan Wang, Jian Kang, Kenji Kawaguchi, Jiaying Wu","categories":"cs.CL, cs.CV","topics":"长视频理解, 时序推理, 模型融合","outline":[2,2]},"headers":[],"relativePath":"papers/2604.11399.md","filePath":"papers/2604.11399.md","lastUpdated":null}'),e={name:"papers/2604.11399.md"};function l(m,s,i,r,c,h){return n(),p("div",null,[...s[0]||(s[0]=[t('<h1 id="lost-in-adaptation-layer-selective-recovery-of-temporal-reasoning-in-video-language-models" tabindex="-1">Lost in Adaptation: Layer-Selective Recovery of Temporal Reasoning in Video-Language Models <a class="header-anchor" href="#lost-in-adaptation-layer-selective-recovery-of-temporal-reasoning-in-video-language-models" aria-label="Permalink to &quot;Lost in Adaptation: Layer-Selective Recovery of Temporal Reasoning in Video-Language Models&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2604.11399" target="_blank" rel="noreferrer">2604.11399</a></td></tr><tr><td><strong>提交日期</strong></td><td>2026-04-13</td></tr><tr><td><strong>作者</strong></td><td>Zihang Fu, Haonan Wang, Jian Kang, Kenji Kawaguchi, Jiaying Wu</td></tr><tr><td><strong>分类</strong></td><td>cs.CL, cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>用 CMA-ES 在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8413em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">L</span></span></span></span></span></span></span></span></span></span></span> 个&quot;每层归 VLM 还是归原始 LLM&quot;的组合里搜一份配方，在保护时序感知不退化的约束下把多模态适配时丢掉的时序推理从预适配语言底座里插值回来，全程无梯度。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/long-video-understanding">长视频理解</a></p></blockquote><p>本页依据 <code>arxiv.org/e-print/2604.11399</code> 的 TeX 源码撰写（ACL 模板，正文分 <code>sections__Introduction.tex</code> / <code>Approach.tex</code> / <code>Experiments.tex</code> / <code>Appendix.tex</code> 与十个表格文件）。 方法在源码中以宏 <code>\\ours{}</code> 出现，对应正式名称 MERIT。</p><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>把一个语言模型改造成视频语言模型，要付出什么代价？这篇论文的答案很具体：时序推理能力。适配之后的模型仍然能看见显著事件——问它&quot;视频里出现了什么&quot;它答得对——但让它推断这些事件的时间顺序和因果结构，它就退化了。作者把这两件事分别命名为时序感知（TP）和时序推理（TR），并用 Video-MME 的两个子集把它们分开测量。</p><p>数字上：LongVA-7B 的 TP 是 60.0，TR 只有 40.1；InternVL3-8B 是 74.5 对 52.0。二十个点的落差不是&quot;视频难&quot;，因为同一个模型的纯文本底座在类似的时序推理题上并不这么差。这是适配过程本身造成的能力侵蚀。</p><p>这个问题重要，是因为它给出了一条不需要新数据、不需要重训的修复路径。如果被侵蚀的能力还完好地保存在预适配的语言底座里，而两个 checkpoint 恰好共享同一套语言架构（多数开源 VLM 都满足这个条件），那么修复就退化成了一个参数插值问题——一个可以在几小时内、不用梯度地解决的问题。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>监督微调</strong>是最直接的修复手段。本文把 LoRA 和全参微调（FFT）放在同样的 232 条样本上做了对照，结果很说明问题：LongVA-7B 上 FFT 把 TP 推到 81.8、TR 推到 64.4，远高于 MERIT 的 61.8/49.7——但这是<strong>在训练集上</strong>的数字。换到未见基准上，FFT 在 Video-Holmes 上从 15.2 崩到 4.7，LongVideoBench Relation 从 48.0 崩到 35.5。LoRA 温和一些但也没有正向迁移（Video-Holmes 15.2→14.5）。232 条样本上的监督拟合会严重过拟合，这是本文给出的最有力的对照证据。</p><p><strong>均匀模型融合</strong>（对整个语言栈施加同一个插值系数）是更接近本文的做法。本文把它拆成两个 baseline：Full-backbone 和 All-attention。LongVA-7B 上 Full-backbone 的 TP/TR 是 60.0/40.1，与 Base 一字不差；All-attention 是 61.8/39.5——TP 略升、TR 反而降。InternVL3-8B 上 Full-backbone 76.4/53.1、All-attention 76.4/54.2，相对 Base 的 74.5/52.0 有小幅提升。也就是说均匀融合在某些骨干上有效但幅度很小，且不稳定。作者的解释是：一个预先设定的、对所有层一致的结构，无法提供同样可迁移的恢复。</p><p><strong>随机层融合</strong>（Random-<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span>，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 与 MERIT 选中的层数相同）是本文最诚实的一个 baseline，而且报了五次运行的均值与标准差。这一点后面会反复用到。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>第一步是一个诊断：把&quot;视频时序能力&quot;拆成感知和推理两个可分别测量的量，然后发现适配只伤了后者。这一步不需要任何新方法，只需要在 Video-MME 上按题型重新分组。</p><p>第二步是问能力去哪了。如果适配前的语言底座还在（多数开源 VLM 会同时发布），那么被侵蚀的能力大概率仍然编码在那份权重里。于是修复变成了&quot;从哪个 checkpoint 取哪部分参数&quot;。</p><p>第三步是选干预粒度。逐 head 会把本来就指数级的搜索空间再乘上 head 数，还会引入对具体架构 head 布局与分组方式的依赖；逐层则在不同模型家族之间通用。作者选层。</p><p>第四步是选干预模块。视频时序推理需要从很长的视觉 token 序列里检索与问题相关的证据，并整合跨越远距离帧的信息——self-attention 直接负责这类输入依赖的交互。所以干预 self-attention，而 MLP、attention+MLP、整块都作为对照。</p><p>第五步是选搜索算法。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8413em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">L</span></span></span></span></span></span></span></span></span></span></span> 的组合空间（28 层就是 2.68 亿种结构），且目标只有在实例化出合并模型并跑完评测之后才可观测，对层分配不可导。这是典型的黑箱组合优化，CMA-ES 是标准选择。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>被多模态适配削掉的能力并没有消失，它还在那份预适配的语言权重里。修复不需要学新参数，只需要决定<strong>每一层该更听谁的</strong>——视觉 grounding 交给适配后的 VLM，时序推理交给原始 LLM。而&quot;该听谁&quot;这个决定必须逐层做，因为均匀地全听 LLM 会破坏感知，全听 VLM 就等于没修。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p><strong>设定</strong>：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span></span></span></span> 是适配后的 VLM，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> 是与之配对的预适配纯文本 LLM，两者共享语言架构。配方 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.625em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span></span></span> 指定 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal">L</span></span></span></span> 个语言层上 self-attention 参数如何组合。</p><p><strong>目标函数</strong>。先定义相对 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span></span></span></span> 的感知退化：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">D</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">TP</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2723em;vertical-align:-0.35em;"></span><span class="mop">max</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord"><span class="mord mathrm">Acc</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.9223em;"><span style="top:-2.453em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">TP</span></span></span></span></span><span style="top:-3.1362em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">base</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord"><span class="mord mathrm">Acc</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">TP</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mclose">)</span><span class="mord"><span class="delimsizing size1">)</span></span><span class="mpunct">,</span></span></span></span></span></p><p>再取</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9331em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7387em;"><span style="top:-3.113em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">∗</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.6861em;vertical-align:-0.8361em;"></span><span class="mop">ar<span style="margin-right:0.0139em;">g</span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop op-limits"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.4306em;"><span style="top:-2.4em;margin-left:0em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0359em;">g</span></span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span><span class="mop">max</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.8361em;"><span></span></span></span></span></span><span class="mspace"> </span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="delimsizing size1">[</span></span><span class="mord"><span class="mord"><span class="mord mathrm">Acc</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">TR</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord mathnormal">λ</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">D</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">TP</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mclose">)</span><span class="mord"><span class="delimsizing size1">]</span></span><span class="mord">.</span></span></span></span></span></p><p>这个惩罚是<strong>单边</strong>的：只在配方伤害感知时激活，超过原 VLM 的部分不受奖励也不受罚。作者把这个非对称性明确称为&quot;修复操作的形式化&quot;。</p><p><strong>层级插值</strong>。连续门控向量 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7335em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0913em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose"><span class="mclose">]</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">L</span></span></span></span></span></span></span></span></span></span></span> 在评测时按 0.5 阈值离散成 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.2222em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span></span></span></span>，然后做方向性插值：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8444em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">ℓ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:3.08em;vertical-align:-1.29em;"></span><span class="minner"><span class="mopen delimcenter" style="top:0em;"><span class="delimsizing size4">{</span></span><span class="mord"><span class="mtable"><span class="col-align-l"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.79em;"><span style="top:-3.79em;"><span class="pstrut" style="height:3.008em;"></span><span class="mord"><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mclose">)</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-2.4169em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">ℓ</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">M</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2831em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-2.4169em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">ℓ</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2831em;"><span></span></span></span></span></span></span><span class="mpunct">,</span></span></span><span style="top:-2.15em;"><span class="pstrut" style="height:3.008em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-2.4169em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">ℓ</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">M</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2831em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mclose">)</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0278em;">θ</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-2.4169em;margin-left:-0.0278em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">ℓ</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2831em;"><span></span></span></span></span></span></span><span class="mpunct">,</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.29em;"><span></span></span></span></span></span><span class="arraycolsep" style="width:1em;"></span><span class="col-align-l"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.79em;"><span style="top:-3.79em;"><span class="pstrut" style="height:3.008em;"></span><span class="mord"><span class="mord"><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.2222em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">ℓ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord">1</span><span class="mspace"> </span><span class="mopen">(</span><span class="mord text"><span class="mord">LLM </span><span class="mord cjk_fallback">主导</span></span><span class="mclose">)</span><span class="mpunct">,</span></span></span><span style="top:-2.15em;"><span class="pstrut" style="height:3.008em;"></span><span class="mord"><span class="mord"><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.2222em;"><span class="mord">^</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">ℓ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mord">0</span><span class="mspace"> </span><span class="mopen">(</span><span class="mord text"><span class="mord">VLM </span><span class="mord cjk_fallback">主导</span></span><span class="mclose">)</span><span class="mpunct">,</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:1.29em;"><span></span></span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span></span></p><p>其中 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5782em;vertical-align:-0.0391em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0.5</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span>。注意这不是&quot;取其一&quot;，两侧永远是混合，只是主导方向不同。</p><p><strong>搜索</strong>。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span></span></span></span> 在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord">1.0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0.9</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0.8</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0.7</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0.6</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0.5</span><span class="mclose">}</span></span></span></span> 上做外层网格，每个 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span></span></span></span> 独立跑一次 CMA-ES 搜层门控，最后取目标值最高的配方。用 <code>mergekit-evolve</code> 实现，每次搜索最多评估 1,600 个候选。</p><p><strong>数据</strong>。搜索信号来自 Video-MME 的 55 条 TP 与 177 条 TR 样本（共 232 条），仅用于选配方与报告 in-domain 诊断分数；Video-MME 剩下的 2,468 条构成留出的 Others 子集。配方定下之后，在四个未见基准上评测：LongVideoBench、LVBench、MMBench-Video、Video-Holmes。</p><p><strong>一个具体的走查</strong>（论文图 example1，Video-Holmes 第 463 题）：视频里男主角在打电话，后面还有受害者被制服、以及受害者倒地不动两个场景。Base 模型锚定在显著的打电话场景上，答成&quot;受害者死于救援不及时&quot;。MERIT 合并后的模型把两个时间上分离但因果相关的事件连起来，答出&quot;受害者是被凶手杀害的&quot;——尽管杀人动作本身没有出现在画面里。作者用答案 token 处的梯度—激活乘积做逐帧归因，显示 MERIT 把重要性分配给了那两个分离的时刻。</p><p><strong>部署</strong>：输出是一个与原 VLM 架构完全相同的单一合并模型，没有额外可训练模块、没有推理期 ensemble、没有额外解码流程。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文的形式化集中在目标函数与插值式上，没有定理，但有两处值得展开。</p><p><strong>为什么单边惩罚是对的。</strong> 若用对称惩罚 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1.1723em;vertical-align:-0.25em;"></span><span class="mord">∣</span><span class="mord"><span class="mord"><span class="mord mathrm">Acc</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.9223em;"><span style="top:-2.453em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">TP</span></span></span></span></span><span style="top:-3.1362em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">base</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord"><span class="mord mathrm">Acc</span></span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">TP</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mclose">)</span><span class="mord">∣</span></span></span></span>，那么一个能同时提升 TP 和 TR 的配方会因为 TP 涨了而被扣分，这显然不合意图。单边形式把问题定义成&quot;以 TP 不低于原 VLM 为约束，最大化 TR&quot;，是一个软化的约束优化。<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal">λ</span></span></span></span> 是拉格朗日乘子的角色，论文没有给它的具体取值。</p><p><strong>搜索空间的真实大小。</strong> <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8413em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">L</span></span></span></span></span></span></span></span></span></span></span> 只是离散门控的数量，实际空间还要乘上 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span></span></span></span> 的 6 个取值。但 CMA-ES 搜索的是连续的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7335em;vertical-align:-0.1944em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">g</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0913em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose"><span class="mclose">]</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">L</span></span></span></span></span></span></span></span></span></span></span>，阈值化发生在评估时——这意味着适应度函数是分段常数的（门控在 0.5 附近的微小变化要么不改变任何东西，要么突然翻转一层）。CMA-ES 在阶梯状适应度上的收敛保证不如在光滑函数上强。论文用三次独立试验的收敛一致性作为经验证据回应了这个担忧：早期轨迹不同但最终目标值收敛到同一处，改进主要发生在约 800–1,200 次评估之间。</p><p><strong>评估噪声的量级</strong>（这一点论文未讨论，属于基于证据的推断）。适应度用 177 条 TR 样本估计，二项分布下单次评估的标准误在 3.7 个百分点量级。CMA-ES 在 1,600 次评估里挑最大值，等于在 1,600 个带 3.7pp 噪声的样本里取极值——这会系统性地高估被选中配方的真实性能。论文报告的 in-domain TR 提升（40.1→49.7）中有多少属于这种选择偏差，无法从现有材料判断。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p>论文按四个 RQ 组织：恢复与迁移、设计验证、功能性干预、时序 grounding。</p><p><strong>RQ1 主表一（<code>tables__main_table1.tex</code>，Video-MME 诊断集）</strong>。LongVA-7B：Base 60.0/40.1/55.0（TP/TR/Others），MERIT 61.8/49.7/55.3，TR 相对提升 23.9%，Others 只动了 +0.5%。InternVL3-8B：Base 74.5/52.0/67.4，Full-backbone 76.4/53.1/67.3，All-attention 76.4/54.2/67.3。LongVA-7B 上的 Random-<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 是 58.9±1.6 / 38.4±1.7 / 54.7±0.5，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span></span></span></span> 调过的 Random-<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8491em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8491em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">†</span></span></span></span></span></span></span></span></span></span></span> 是 59.6±0.8 / 40.8±0.9 / 54.8±0.5。三个骨干的 TR 相对提升分别是 23.9%、10.8%、3.8%，Others 变化 +0.5% / +0.7% / -1.1%。</p><p><strong>RQ1 主表二（<code>tables__main_table2.tex</code>，四个未见基准）</strong>。LongVA-7B 一行：Base 的 LongVideoBench Relation/Overall 是 48.0/52.5，LVBench TR/Overall 是 45.3/37.6，MMBench-Video TR/Overall 是 1.05/1.27，Video-Holmes 15.2。MERIT 对应 48.6/53.6、46.8/39.7、1.09/1.29、18.9。作者声称 15 个 reasoning-aligned 比较全部为正，12 个未见设置中 11 个 Overall 也提升，最大相对增益是 MMBench-Video TR 的 27.8% 与 Video-Holmes 的 24.3%。</p><p><strong>但把 Random-<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8491em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8491em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">†</span></span></span></span></span></span></span></span></span></span></span> 那一行摆在旁边，图景就变了</strong>：LongVideoBench Relation 48.2±0.7 对 MERIT 的 48.6；LVBench TR 45.3±1.8 对 46.8；MMBench-Video TR 1.07±0.01 对 1.09；Video-Holmes 15.8±2.5 对 18.9。前三项 MERIT 都落在随机层基线的一个标准差之内，只有 Video-Holmes 明显在外。而 Video-Holmes 恰好是 Random-<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 标准差最大的一项（±2.5 与 ±3.8）。</p><p><strong>RQ2 设计验证</strong>。三次独立 CMA-ES 试验在同样 1,600 候选预算下收敛到同一目标值。成本表（<code>tables__cost_efficiency.tex</code>）：全部测量在 NVIDIA A100-SXM4-80GB 上，FFT 用 8 卡、1 epoch/29 步、7.61B 可训练参数、约 0.5 小时；LoRA 用 4 卡、3 epoch/174 步、40.37M 可训练参数；MERIT 用 4 卡 16 worker，在 InternVL3-8B 上完整搜索约 1.7 小时，无梯度更新、无可训练参数。干预模块对比（<code>tables__attention_mlp_ablation.tex</code>）显示 attention-only 在三个基准上最强且最可迁移，MLP-only 几乎无收益。</p><p><strong>RQ3 干预掩蔽</strong>。把 MERIT 选中的层的 self-attention 输出乘以 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">κ</span></span></span></span>（保留残差连接），在 LVBench 上测相对退化 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">Δ</span><span class="mopen">(</span><span class="mord mathnormal">κ</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.53em;vertical-align:-0.52em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:1.01em;"><span style="top:-2.655em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">Score</span></span><span class="mopen mtight">(</span><span class="mord mtight">1.0</span><span class="mclose mtight">)</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.485em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathrm mtight">Score</span></span><span class="mopen mtight">(</span><span class="mord mtight">1.0</span><span class="mclose mtight">)</span><span class="mbin mtight">−</span><span class="mord mtight"><span class="mord mathrm mtight">Score</span></span><span class="mopen mtight">(</span><span class="mord mathnormal mtight">κ</span><span class="mclose mtight">)</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.52em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span></span></span></span>。LongVA-7B 在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">κ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.4</span></span></span></span> 时 Reasoning 掉 35.1%、Overall 掉 16.8%、Others 只掉 2.7%；完全抑制时 Reasoning 掉 51.7%。InternVL3-8B 在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">κ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span> 时三者分别是 58.2%、44.2%、35.2%。</p><p>第二个骨干上的分离度明显更小（58.2 vs 35.2，比值 1.65），而 LongVA 上是 51.7 vs 更低的 Others（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">κ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.4</span></span></span></span> 时比值 13）。论文只在正文里展开了 LongVA 的数字。</p><p><strong>RQ4 归因</strong>。在答案 token 处按 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">s</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0913em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-2.453em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathcal mtight" style="margin-right:0.0583em;">C</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord mathnormal">c</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.1274em;vertical-align:-0.2861em;"></span><span class="mop"><span class="mop">max</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight">c</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6828em;"><span style="top:-2.786em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span></span></span></span></span><span class="mrel mtight"><span class="mrel mtight"><span class="mord vbox mtight"><span class="thinbox mtight"><span class="rlap mtight"><span class="strut" style="height:0.8889em;vertical-align:-0.1944em;"></span><span class="inner"><span class="mord mtight"><span class="mrel mtight"></span></span></span><span class="fix"></span></span></span></span></span><span class="mspace nobreak mtight"></span><span class="mrel mtight">=</span></span><span class="mord mathnormal mtight">c</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-2.453em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathcal mtight" style="margin-right:0.0583em;">C</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">c</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.7519em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">′</span></span></span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span> 定义归因目标，逐帧重要性 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.0785em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.4001em;vertical-align:-0.52em;"></span><span class="mop"><span class="mop op-symbol small-op" style="position:relative;top:0em;">∑</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1864em;"><span style="top:-2.4003em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2997em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop"><span class="mop op-symbol small-op" style="position:relative;top:0em;">∑</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.162em;"><span style="top:-2.4003em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.4358em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">∣</span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8801em;"><span style="top:-2.655em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight" style="margin-right:0.0556em;">∂</span><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2963em;"><span style="top:-2.357em;margin-left:-0.2222em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span><span class="mopen mtight">[</span><span class="mord mathnormal mtight" style="margin-right:0.0315em;">k</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span><span class="mclose mtight">]</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.394em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight" style="margin-right:0.0556em;">∂</span><span class="mord mathnormal mtight">s</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.52em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.2222em;">V</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.2222em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">[</span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0572em;">j</span><span class="mclose">]</span><span class="mord">∣</span></span></span></span>，min-max 归一化。作者说明评测用 64 帧而图里只画 12 帧，归因分数在 5 帧邻域上做了平滑，展示帧按归因排名并结合与生成推理轨迹的一致性挑选。这一节只给了定性案例，没有统计量。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：多模态适配会侵蚀时序推理但不侵蚀时序感知，两者在 Video-MME 上可以分开测量，落差可达二十个点。MERIT 假设被侵蚀的能力还完好保存在配对的预适配语言底座里，于是把修复化归为&quot;每个 self-attention 层该由 VLM 主导还是 LLM 主导&quot;的组合搜索，用 CMA-ES 在 1,600 候选预算内求解，目标是最大化 TR 且单边惩罚 TP 退化。搜索只用 232 条 Video-MME 样本作为黑箱验证信号，不更新任何参数，输出是架构与原 VLM 完全相同的单一模型。在 A100 上 InternVL3-8B 的完整搜索约 1.7 小时，与 LoRA 相当，但无梯度、无可训练参数、无部署开销。三个骨干上 TR 相对提升 23.9%/10.8%/3.8%，配方能迁移到四个未见基准，最大相对增益 27.8%（MMBench-Video TR）与 24.3%（Video-Holmes）。</p><p><strong>3 句话版</strong>：把能力退化的修复从&quot;再训一次&quot;换成&quot;在两份现成权重之间逐层选边&quot;，用演化策略搜那 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8413em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">L</span></span></span></span></span></span></span></span></span></span></span> 个组合。在 232 条样本上选出的配方能迁移到未见基准，而在同样 232 条上做 LoRA/FFT 则严重过拟合（FFT 在 Video-Holmes 上从 15.2 崩到 4.7）。但在多数迁移基准上，MERIT 与随机选层基线的差距落在后者的一个标准差之内。</p><p><strong>1 句话版</strong>：适配丢掉的时序推理还在原始 LLM 里，逐层插值把它接回来就行，不用梯度。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的假设是：<strong>在 232 条样本上选出的配方，其收益不是搜索过程对这 232 条的过拟合。</strong></p><p>这不是一个抽象的担忧，论文自己的实验就在同一批 232 条样本上展示了过拟合的样子：FFT 在这批样本上把 TR 推到 64.4，转到 Video-Holmes 就崩到 4.7。MERIT 与 FFT 的区别是搜索空间小得多（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.9247em;vertical-align:-0.0833em;"></span><span class="mord"><span class="mord">2</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8413em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">L</span></span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">6</span></span></span></span> 个离散配方 vs 7.61B 个连续参数），所以过拟合应当更轻——但&quot;更轻&quot;不等于&quot;没有&quot;。CMA-ES 在 1,600 个候选里取适应度最大值，而适应度由 177 条 TR 样本估计。在这个规模下，单次评估的采样噪声在 3.7 个百分点量级（推断值，论文未报），而 1,600 次取极值会把噪声的正尾挑出来。</p><p>论文给的迁移证据部分回应了这一点：配方在四个未见基准上确实为正。但<strong>把 Random-<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8491em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8491em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">†</span></span></span></span></span></span></span></span></span></span></span> 的标准差摆上去，回应就变弱了</strong>。LongVA-7B 上，LongVideoBench Relation 是 48.6 对 48.2±0.7，LVBench TR 是 46.8 对 45.3±1.8，MMBench-Video TR 是 1.09 对 1.07±0.01（这一项差距在 2 个标准差外）。三项里两项落在随机基线的 1σ 内。而 MERIT 自己<strong>没有报标准差</strong>——它是一次搜索的一个配方，虽然搜索本身跑了三次并收敛到同一目标值，但&quot;同一目标值&quot;是在诊断集上说的，不是在迁移基准上说的。</p><p>这个缺口的代价：如果 MERIT 的迁移增益与随机选 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 层不可区分，那么核心贡献就从&quot;层选择很重要&quot;退化为&quot;用预适配 LLM 做部分插值有帮助&quot;——后者是 Full-backbone/All-attention 已经展示过的、且成本为零的结论。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不需要复现 CMA-ES 搜索，一周内可完成前两项。</p><ol><li><strong>给 MERIT 加误差棒</strong>（三天，最关键）。跑五次独立的 CMA-ES 搜索（不同随机种子），每次得到一个配方，各自在四个未见基准上评测。报五个配方在每个基准上的均值与标准差。与论文已有的 Random-<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8491em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8491em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">†</span></span></span></span></span></span></span></span></span></span></span> 的均值/标准差直接做两样本比较。</li><li><strong>测搜索的选择偏差</strong>（两天）。把 232 条诊断样本随机对半分成 A、B 两份。只用 A 跑搜索，选出配方后同时报 A 上的分数（被优化过）与 B 上的分数（未被优化）。两者的差值就是选择偏差的直接估计。若 A 上是 49.7 而 B 上回落到 43，那么论文报的 in-domain TR 提升有一大半是搜索噪声。</li><li><strong>补一个更强的平凡基线</strong>（一天）。除了 Random-<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span>，加一个&quot;按层深度取前 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 层 / 后 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 层 / 中间 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 层&quot;的确定性基线。如果某个固定位置的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 层就能达到 MERIT 的水平，那么搜索本身可以省掉。</li></ol><p><strong>判据</strong>：第 1 步中若五个配方的均值减去 Random-<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8491em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0315em;">k</span><span class="msupsub"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8491em;"><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mbin mtight">†</span></span></span></span></span></span></span></span></span></span></span> 的均值小于两者标准差之和，则层选择的价值未被证实；第 2 步中若 A、B 的差值超过 4 个点，则 in-domain 数字不可作为能力恢复的证据。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p><strong>替代解释攻击：增益来自&quot;稀释适配&quot;而非&quot;选对层&quot;。</strong> 构造一个纯剂量对照——不做任何层选择，把<strong>所有</strong> self-attention 层都用同一个 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span></span></span></span> 插值，但把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span></span></span></span> 在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0.5</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">1</span><span class="mclose">]</span></span></span></span> 上细扫（论文只在 6 个点上试过，且 All-attention 只取了一个），在同一个 232 条诊断集上选最优 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span></span></span></span>，再评迁移。如果这个&quot;零结构、只调剂量&quot;的做法在四个未见基准上与 MERIT 差距小于随机基线的标准差，那么标题里的 &quot;Layer-Selective&quot; 就没有实证支撑。这个反例有先验支持：InternVL3-8B 上 All-attention 的 TR 是 54.2，已经拿到了 Base（52.0）到 MERIT（论文报相对 +10.8%，即约 57.6）之间的相当一部分。</p><p><strong>可预测的失败场景：没有配对底座的模型。</strong> 方法的前提是&quot;<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> 共享语言架构且两者都可得&quot;。这个条件对 LongVA、InternVL3、Qwen3-VL 成立，但对从头联合预训练的多模态模型（不存在&quot;预适配语言 checkpoint&quot;这个东西）完全不成立，对闭源模型也不成立。论文在设定一节承认了这个假设，但没有讨论它排除了多大一片模型空间。审稿人可以要求作者说明：在当前主流 VLM 中，有多大比例满足这个配对条件。</p><p><strong>功能性证据的替代解释。</strong> RQ3 的掩蔽实验声称&quot;选中的层对 TR 功能上重要&quot;。但这个实验只掩蔽了 MERIT 选中的层，没有掩蔽同样数量的随机层作为对照。缺了这个对照，35.1% vs 2.7% 的分离度无法排除一个更平凡的解释：<strong>任意</strong> <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 个中间 self-attention 层被抑制，都会让需要多步推理的题目比需要单步识别的题目掉得更快，因为推理题对模型容量的边际敏感度本来就更高。补一个 Random-<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord mathnormal" style="margin-right:0.0315em;">k</span></span></span></span> 掩蔽曲线，是这个反例最省力的形式。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：MERIT 把&quot;哪些层该归谁&quot;当成一个需要 1,600 次昂贵评测才能解答的黑箱问题。但它同时又用一个诊断实验（RQ3 掩蔽）说明选中的层在功能上可识别。这两件事是矛盾的——如果掩蔽实验能识别出这些层，那为什么还需要演化搜索？换句话说，本文有一个<strong>便宜的诊断信号</strong>和一个<strong>昂贵的搜索</strong>，却没有把前者用来替代后者。</p><p><strong>可借鉴的相邻工具</strong>：模型编辑与机制可解释性里的 causal tracing / activation patching。它的做法是逐层把干净运行的激活替换进被破坏的运行，测量哪一层的替换恢复了正确输出——一次前向对若干层，成本远低于实例化并评测整个合并模型。</p><p><strong>新的 framing</strong>：把配方从&quot;搜出来&quot;变成&quot;<strong>测出来</strong>&quot;。具体做法是对每一层做一次 activation patching：在 VLM 的前向过程中，把第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord">ℓ</span></span></span></span> 层 self-attention 的输出替换成同一层在预适配 LLM 权重下的输出，测量 TR 题目的 logit margin 变化。这给出一个逐层的&quot;恢复效应&quot;向量，<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal" style="margin-right:0.0278em;">O</span><span class="mopen">(</span><span class="mord mathnormal">L</span><span class="mclose">)</span></span></span></span> 次前向即可得到，而不是 1,600 次完整评测。然后直接把恢复效应为正的层设为 LLM 主导。这不是对 MERIT 的增量改进，它把整类问题从组合优化重新表述为因果测量——而且顺带解决了 §9 的选择偏差问题，因为逐层效应是逐个测的，不涉及在大量候选里取极值。</p><p><strong>第一个实验</strong>：在 InternVL3-8B 上，对全部 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal">L</span></span></span></span> 层各做一次 activation patching，用 232 条诊断集的 TR 子集算 logit margin 的平均变化，得到恢复效应向量。把它与 MERIT 搜出来的配方（论文附录报了选中的层）做秩相关。若相关系数高于 0.6，说明廉价诊断能替代搜索；若接近 0，那么 MERIT 找到的是层间<strong>交互</strong>结构而非单层效应，这本身就是一个更有意思的结论——它意味着时序推理的恢复不能被分解成逐层贡献，而现有的所有逐层可解释性工具都会漏掉它。</p>',70)])])}const d=a(e,[["render",l]]);export{o as __pageData,d as default};
